export function registerAccountFlowTests(test, expect) {

test('Create account validates inputs, walks all onboarding steps, and updates the profile', async ({ page }) => {
  await page.goto('/')
  await page.getByRole('button', { name: 'New here? Create an account' }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'join')
  await page.getByRole('button', { name: 'Create account', exact: true }).click()
  await expect(page.locator('.form [role="alert"]')).toContainText('3–20')
  await page.getByLabel('Handle', { exact: true }).fill('rae')
  await page.getByLabel('Email', { exact: true }).fill('demo@example.com')
  await page.getByLabel('Demo password', { exact: true }).fill('not-a-real-password')
  await page.getByRole('button', { name: 'Create account', exact: true }).click()
  await expect(page.locator('.form [role="alert"]')).toContainText('taken')
  await page.getByLabel('Handle', { exact: true }).fill('demo_music')
  await expect(page.locator('.available')).toContainText('Available in this demo')
  await page.getByRole('button', { name: 'Create account', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'check-email')
  await expect(page.locator('#screen')).toContainText('demo@example.com')
  await expect(page.locator('#screen')).toContainText('No email is sent')
  await page.getByRole('button', { name: 'Resend link' }).click()
  await expect(page.locator('#toast')).toContainText('no verification email')
  await page.getByRole('button', { name: 'Continue with demo verification' }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'onboarding-avatar')
  const avatar = page.locator('.av-preview svg')
  const before = await avatar.innerHTML()
  await page.getByRole('button', { name: 'Next Hair', exact: true }).click()
  expect(await avatar.innerHTML()).not.toBe(before)
  const saved = await avatar.innerHTML()
  await page.getByRole('button', { name: 'Next', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'onboarding-genres')
  const next = page.getByRole('button', { name: 'Next', exact: true })
  await expect(next).toBeDisabled()
  await expect(page.locator('.genre-chips button')).toHaveCount(14)
  for (const genre of ['Pop', 'Rock', 'Jazz']) await page.getByRole('button', { name: genre, exact: true }).click()
  await expect(next).toBeEnabled()
  await next.click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'onboarding-friends')
  await page.getByLabel('Search by @handle').fill('noor')
  await expect(page.locator('.rows li')).toHaveCount(1)
  await page.getByRole('button', { name: 'Add', exact: true }).click()
  await expect(page.getByRole('button', { name: 'Requested', exact: true })).toBeVisible()
  await page.getByRole('button', { name: 'Finish', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'welcome')
  await expect(page.locator('#screen')).toContainText('@demo_music')
  await page.getByRole('button', { name: 'Explore Discover' }).click()
  await page.getByRole('button', { name: 'Profile', exact: true }).click()
  await expect(page.locator('.handle-xl')).toHaveText('@demo_music')
  expect(await page.locator('.me-card .av svg').innerHTML()).toBe(saved)
})

test('Settings preferences, cancel, Done, and logout preserve demo content', async ({ page }) => {
  await page.goto('/#/profile')
  await page.getByRole('button', { name: 'Chats', exact: true }).click()
  await page.locator('.chat-row').first().click()
  await page.getByRole('textbox', { name: 'Message', exact: true }).fill('Keep this demo message')
  await page.getByRole('button', { name: 'Send', exact: true }).click()
  await page.getByRole('button', { name: 'Back', exact: true }).click()
  await page.getByRole('button', { name: 'Profile', exact: true }).click()
  await page.getByRole('button', { name: 'Settings', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'settings')
  await page.getByRole('button', { name: 'Notifications On' }).click()
  await expect(page.getByRole('button', { name: 'Notifications Off' })).toBeVisible()
  await page.getByRole('button', { name: 'Privacy Friends only' }).click()
  await expect(page.getByRole('button', { name: 'Privacy Public' })).toBeVisible()
  await page.getByLabel('Appearance', { exact: true }).selectOption('dark')
  await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark')
  await page.getByRole('button', { name: 'Log out', exact: true }).click()
  await expect(page.getByRole('dialog')).toBeVisible()
  await expect(page.getByRole('button', { name: 'Cancel', exact: true })).toBeFocused()
  await page.keyboard.press('Tab')
  await expect(page.getByRole('button', { name: 'Log out', exact: true })).toBeFocused()
  await page.keyboard.press('Shift+Tab')
  await expect(page.getByRole('button', { name: 'Cancel', exact: true })).toBeFocused()
  await page.getByRole('button', { name: 'Cancel', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'settings')
  await page.getByRole('button', { name: 'Done', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'profile')
  await page.getByRole('button', { name: 'Settings', exact: true }).click()
  await page.getByRole('button', { name: 'Log out', exact: true }).click()
  await page.getByRole('button', { name: 'Log out', exact: true }).click()
  await expect(page.locator('#screen')).toHaveAttribute('data-screen', 'signin')
  await page.getByRole('button', { name: 'Sign in', exact: true }).click()
  await page.getByRole('button', { name: 'Chats', exact: true }).click()
  await page.locator('.chat-row').first().click()
  await expect(page.locator('.msgs')).toContainText('Keep this demo message')
})
}
